/* Real RF/causal-TCN inference. Parameters are exported from verified trained bundles. */
export const labels=['Normal','Damper fault','Cooling valve fault','Heating valve fault'];
const maxIndex=a=>a.indexOf(Math.max(...a));
export const softmax=(a,t=1)=>{let z=a.map(x=>x/t),m=Math.max(...z),e=z.map(x=>Math.exp(x-m)),s=e.reduce((x,y)=>x+y,0);return e.map(x=>x/s)};
const calibrate=(p,t)=>softmax(p.map(x=>Math.log(Math.max(1e-12,Math.min(1,x)))),t);
// Abramowitz-Stegun erf approximation; max absolute error below 1.5e-7.
function erf(x){let sign=x<0?-1:1; x=Math.abs(x);let t=1/(1+.3275911*x);return sign*(1-(((((1.061405429*t-1.453152027)*t)+1.421413741)*t-.284496736)*t+.254829592)*t*Math.exp(-x*x))}
const gelu=x=>.5*x*(1+erf(x/Math.SQRT2));
function linear(x,w,b){return w.map((row,i)=>row.reduce((s,a,j)=>s+a*x[j],b?b[i]:0))}
function conv(x,w,b,d){return x.map((_,t)=>w.map((weights,o)=>{let sum=b[o];for(let c=0;c<weights.length;c++)for(let k=0;k<weights[c].length;k++){let ti=t-(weights[c].length-1-k)*d;if(ti>=0)sum+=weights[c][k]*x[ti][c]}return sum}))}
function norm(x,w,b){return x.map(row=>{let mean=row.reduce((a,b)=>a+b,0)/row.length;let v=row.reduce((s,a)=>s+(a-mean)**2,0)/row.length;return row.map((a,j)=>(a-mean)/Math.sqrt(v+1e-5)*w[j]+b[j])})}
function encode(seq,state){let x=seq;for(let i=0;i<3;i++){let k=`blocks.${i}.`,prev=x;let a=conv(x,state[k+'first.conv.weight'],state[k+'first.conv.bias'],2**i);a=norm(a,state[k+'first_norm.weight'],state[k+'first_norm.bias']).map(r=>r.map(gelu));a=conv(a,state[k+'second.conv.weight'],state[k+'second.conv.bias'],2**i);a=norm(a,state[k+'second_norm.weight'],state[k+'second_norm.bias']);let skip=state[k+'skip.weight']?conv(prev,state[k+'skip.weight'],state[k+'skip.bias'],1):prev;x=a.map((r,t)=>r.map((v,j)=>gelu(v+skip[t][j])))}return x}
export function temporal(seq,state,kind){let encoded=encode(seq,state),summary=encoded.at(-1),attention=null;if(kind!=='causal_tcn_last'){let scores=encoded.map(r=>linear(linear(r,state['attention_score.0.weight'],state['attention_score.0.bias']).map(Math.tanh),state['attention_score.2.weight'],null)[0]);attention=softmax(scores);let pool=encoded[0].map((_,c)=>encoded.reduce((s,r,t)=>s+r[c]*attention[t],0));summary=kind==='causal_tcn_combined'?[...summary,...pool]:pool}let logits=kind==='causal_tcn_combined'?linear(linear(summary,state['classifier.0.weight'],state['classifier.0.bias']).map(gelu),state['classifier.3.weight'],state['classifier.3.bias']):linear(summary,state['classifier.weight'],state['classifier.bias']);return {logits,attention}}
export function tabular(raw){let f=Math.fround,arr=[],mean32=col=>f(col.reduce((s,v)=>f(s+v),0)/15);for(let type of ['mean','std','min','max','last','trend'])for(let j=0;j<10;j++){let col=raw.map(r=>f(r[j])),mean=mean32(col);arr.push(type==='mean'?mean:type==='std'?f(Math.sqrt(f(col.reduce((sum,v)=>{let d=f(v-mean);return f(sum+f(d*d))},0)/15))):type==='min'?Math.min(...col):type==='max'?Math.max(...col):type==='last'?col[14]:f(f(col[14]-col[0])/14))}for(let [a,b] of [[0,2],[2,3],[1,3]]){let d=raw.map(r=>f(f(r[a])-f(r[b])));arr.push(mean32(d),d[14])}return arr.map(f)}
function forest(tab,trees){let p=[0,0,0,0];for(let t of trees){let n=0;while(t.left[n]!==-1)n=tab[t.feature[n]]<=t.threshold[n]?t.left[n]:t.right[n];for(let c=0;c<4;c++)p[c]+=t.value[n][c]/trees.length}return p}
const artifactCache=new Map();
export async function jsonGzip(url){if(artifactCache.has(url))return artifactCache.get(url);let r=await fetch(url);if(!r.ok)throw Error('Model artifact is unavailable: '+url);let ds=r.body.pipeThrough(new DecompressionStream('gzip'));let data=JSON.parse(await new Response(ds).text());artifactCache.set(url,data);return data}
export async function loadModel(info){let [trees,state]=await Promise.all([jsonGzip(info.forest_url),jsonGzip(info.temporal_url)]);return {...info,trees,state}}
export function predict(model,raw,prepared=null){let c=model.config,seq=prepared?prepared.seq:raw.map(r=>r.map((v,j)=>Math.fround((Math.fround(v)-model.scaler.mean[j])/model.scaler.scale[j])));let tab=prepared?prepared.tab:tabular(raw);let nn=temporal(seq,model.state,c.temporal_kind);let f=calibrate(forest(tab,model.trees),c.temperatures.forest),t=softmax(nn.logits,c.temperatures.temporal);let p=calibrate(f.map((v,i)=>c.forest_weight*v+(1-c.forest_weight)*t[i]),c.temperatures.hybrid);let cls=maxIndex(p),confidence=p[cls],disagree=maxIndex(f)!==maxIndex(t);return {class_id:cls,confidence,probabilities:p,forest_probabilities:f,temporal_probabilities:t,branch_disagreement:disagree,attention:nn.attention,seq}}
const settings={CoolingSeason:[0,1,2],HeatingSeason:[0,1,3],ShoulderSeason:[0,1,2]};
export function diagnose(model,raw,setting,time,recordedSource=false){let blocked=[];if(!Array.isArray(raw)||raw.length!==15||raw.some(r=>r.length!==10||r.some(v=>!Number.isFinite(v))))blocked.push('Require 15 complete rows of 10 finite sensor values.');else{if(raw.some(r=>r.slice(0,4).some(v=>v< -60||v>100)||r.slice(5,9).some(v=>v< -1e-6||v>1+1e-6)))blocked.push('Sensor values exceed physical input bounds.');if(raw.some(r=>r[4]!==1||r[9]!==1))blocked.push('Occupied operation and a running supply fan are required.')}if(!time||time.length!==15||time.some((v,i)=>!Number.isFinite(v)||(i&&Math.abs(v-time[i-1]-60)>1e-6)))blocked.push('Require 15 consecutive one-minute timestamps.');if(blocked.length)return {status:'blocked',reasons:blocked};let p=predict(model,raw),reasons=[];if(!recordedSource&&settings[setting])reasons.push('Uploaded or unverified AHU context requires review.');if(!settings[setting])reasons.push('Exploratory AHU setting: transfer is unvalidated.');else if(!settings[setting].includes(p.class_id))reasons.push('Predicted class is outside observed class/season coverage.');if(model.config.learning_stage==='verified_feedback')reasons.push('Experimental reference-feedback candidate: source retention is not operational approval.');if(p.confidence<.9)reasons.push('Confidence is below the provisional 0.90 threshold.');if(p.branch_disagreement)reasons.push('Classical and temporal branches disagree.');let out=p.seq.filter(r=>r.some(v=>Math.abs(v)>6)).length;if(out)reasons.push(`${out}/15 samples exceed the source-scale support bound.`);return {...p,status:reasons.length?'review_required':'research_prediction',reasons,source_support_warning_samples:out,automatic_actuation_allowed:false,policy_version:'m4-research-review-v2'}}
